<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class SupplierInvoice extends Model {protected $fillable=['invoice_number','supplier_id','purchase_order_id','goods_receipt_id','invoice_date','due_date','subtotal','discount','tax','total','paid_amount','remaining_amount','status','notes']; protected $casts=['invoice_date'=>'date','due_date'=>'date','subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','total'=>'decimal:2','paid_amount'=>'decimal:2','remaining_amount'=>'decimal:2']; public function supplier():BelongsTo{return $this->belongsTo(Supplier::class);} public function payments():HasMany{return $this->hasMany(SupplierPayment::class);} }
